#include "source_import_analyzer.h"
#include "library_sql.h"

#include <assert.h>
#include <stdio.h>
#include <string.h>

const struct az_library_sql *az_storage_sql(void) { return NULL; }
const char *az_storage_mountinfo(void) { return "/dev/null"; }
int az_storage_stick_mount(int stick, char *path, size_t capacity) {
    (void) stick;
    (void) path;
    (void) capacity;
    return 0;
}

static void locator_fixtures(void) {
    /* These files were independently generated by native 2.00 raw analysis. */
    const struct {
        const char *audio, *locator;
    } cases[] = {
        {"/SDKTEST/fresh-control.m4a", "/PIONEER/USBANLZ/P051/00011239/ANLZ0000.DAT"},
        {"/SDKTEST/standalone-analysis.m4a", "/PIONEER/USBANLZ/P07A/0001A686/ANLZ0000.DAT"},
        {"/AZ-MODS-IMPORTS/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/track.m4a",
         "/PIONEER/USBANLZ/P01D/0000DEF1/ANLZ0000.DAT"},
    };
    char locator[AZ_SOURCE_PATH_BYTES];
    for (unsigned i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        assert(azspi_analyzer_locator(cases[i].audio, locator) == AZ_OK);
        assert(!strcmp(cases[i].locator, locator));
    }
}

static void invalid_paths(void) {
    const char *const invalid[] = {NULL, "", "/", "track.m4a", "/a/../track.m4a", "/./track.m4a",
                                   "/a//track.m4a", "/a/", "/a\\track.m4a", "/a/track\n.m4a", "/a/\xc3\xa9.m4a",
                                   "/1/2/3/4/5/6/7/8/9/track.m4a"};
    char locator[AZ_SOURCE_PATH_BYTES] = "unchanged";
    for (unsigned i = 0; i < sizeof(invalid) / sizeof(invalid[0]); ++i) {
        assert(azspi_analyzer_locator(invalid[i], locator) == AZ_INVALID);
        assert(!strcmp(locator, "unchanged"));
    }
    char oversized[AZ_SOURCE_PATH_BYTES + 1];
    memset(oversized, 'a', sizeof oversized);
    oversized[0] = '/';
    oversized[sizeof oversized - 1] = 0;
    assert(azspi_analyzer_locator(oversized, locator) == AZ_INVALID);
    oversized[257] = 0;
    assert(azspi_analyzer_locator(oversized, locator) == AZ_INVALID);
    assert(azspi_analyzer_locator("/track.m4a", NULL) == AZ_INVALID);
}

static void native_admission_refuses_unqualified_inputs(void) {
    struct st_source source = {.mount = "/tmp"};
    uint8_t raw[AZSPI_NATIVE_TRACK_BYTES] = {0x5a};
    uintptr_t database[9] = {0};
    const char *audio = "/az-source-import-analyzer/unit-fixture.m4a";
    assert(azspi_analyzer_submit(1, NULL, 0, NULL, NULL, NULL) == AZ_UNSUPPORTED);
    assert(azspi_analyzer_submit(2, NULL, 0, NULL, audio, raw) == AZ_INVALID);
    assert(azspi_analyzer_submit(2, NULL, 0, &source, audio, NULL) == AZ_INVALID);
    assert(azspi_analyzer_submit(2, NULL, 0, &source, "/../track.m4a", raw) == AZ_INVALID);
    assert(azspi_analyzer_submit(2, NULL, 0, &source, audio, raw) == AZ_STALE);
    assert(azspi_analyzer_submit(2, database, 0x102, &source, audio, raw) == AZ_STALE);
    assert(raw[0] == 0x5a);
}

int main(void) {
    locator_fixtures();
    invalid_paths();
    native_admission_refuses_unqualified_inputs();
    puts("PASS source import analyzer locator and admission");
    return 0;
}
